[asy]
draw((0,0)--(0,10)--(30,10)--(30,0)--cycle);
draw((10,0)--(10,10));
draw((20,0)--(20,10));
draw((0,10)--(20,0),linewidth(1));
label("$A$",(0,10),NW);
label("$B$",(20,0),S);
